class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        count = 0
        n = len(nums)
        for i in range(n - 2):
            # Check if the sum of the first and third numbers equals half of the middle number
            # To avoid floating point division issues, we multiply by 2
            if 2 * (nums[i] + nums[i+2]) == nums[i+1]:
                count += 1
        return count
